WITH cleaned AS (SELECT id, reading_ts, humidity, pressure, status_bits, COALESCE(pressure, 0) pressure_filled FROM device_readings WHERE firmware = '2.0.1') SELECT *, SUM(humidity) OVER (ORDER BY pressure_filled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_humidity, ROW_NUMBER() OVER (ORDER BY pressure, id) event_seq, LEAD(pressure_filled, 1) OVER (ORDER BY pressure_filled, id) next_pressure_filled, DENSE_RANK() OVER (ORDER BY status_bits) status_bits_dense_rank, LAST_VALUE(pressure_filled) IGNORE NULLS OVER (ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_pressure_filled FROM cleaned;
